(()=>{const root=document.querySelector('.rider-search--header'),toggle=document.querySelector('#rider-search-toggle'),panel=root?.querySelector('.rider-search-popover'),input=document.querySelector('#rider-search-input'),list=document.querySelector('#rider-search-results');if(!root||!toggle||!panel||!input||!list)return;let timer,controller;const close=()=>{clearTimeout(timer);list.innerHTML='';list.hidden=true;panel.hidden=true;toggle.setAttribute('aria-expanded','false')};const open=()=>{panel.hidden=false;toggle.setAttribute('aria-expanded','true');input.focus()};const render=rows=>{if(!rows.length){list.innerHTML='<p>No rider found.</p>';list.hidden=false;return}list.innerHTML=rows.map(r=>'<a href="/rider/?id='+encodeURIComponent(r.id)+'">'+String(r.name).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</a>').join('');list.hidden=false};toggle.addEventListener('click',()=>panel.hidden?open():close());input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<2&&!/^\d+$/.test(q)){list.innerHTML='';list.hidden=true;return}timer=setTimeout(async()=>{if(controller)controller.abort();controller=new AbortController;try{const response=await fetch('/api/public/riders/search?name='+encodeURIComponent(q),{signal:controller.signal,cache:'no-store'});if(!response.ok)throw Error();render(await response.json())}catch(error){if(error.name!=='AbortError'){list.innerHTML='';list.hidden=true}}},180)});input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();toggle.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.rider-search--header'))close()})})();
